function spaceAlreadyAssigned(state,name){return assignedRecordsFor(state).some(function(row){return state.selectedTables.indexOf(row.table)>-1&&(row.spaces||[]).indexOf(name)>-1})}
function spaceTreeHtml(state){return wizardSpaces.map(function(space,index){var checked=state.spaces.has(space.name),locked=spaceAlreadyAssigned(state,space.name),focused=state.focusSpace===space.name;return '<div class="ds-space-row '+(checked?'selected ':'')+(focused?'focused ':'')+(locked?'locked ':'')+space.kind+'" style="--level:'+space.level+'"><label><input type="checkbox" data-wiz-space="'+esc(space.name)+'" '+(checked?'checked':'')+' '+(locked?'disabled':'')+'><i>'+((index<4&&space.level<3)||index===0?'⌄':'')+'</i><em>'+(space.kind==='personal'?'人':space.kind==='enterprise'?'企':'组')+'</em><span data-wiz-focus="'+esc(space.name)+'"><b>'+esc(space.name)+'</b><small>'+(locked?'已分配所选数据表，不可重复分发':space.kind==='personal'?'个人空间 · 当前用户可用':'组织空间 · 当前用户为成员')+'</small></span></label><button type="button" data-wiz-space-history="'+esc(space.name)+'" title="查看该空间已分配库表">查看已分配信息</button></div>'}).join('')}
