function mergeAssignment(source,table,spaces,time,fields){
 source.assignments=source.assignments||[];
 spaces.forEach(function(space){var existing=source.assignments.find(function(item){return item.table===table&&(item.spaces||[]).indexOf(space)>-1});if(existing){existing.fields=fields?fields.slice():null;existing.time=time}else source.assignments.push({table:table,spaces:[space],fields:fields?fields.slice():null,time:time})})
}
function completeWizard(state,wizard,list,leftSearch,withAssignments){
 if(!state.connected){toast('连接信息已修改，请重新测试连接');return}
 if(!state.name.trim()){toast('请在第 1 步填写数据源名称');return}
 if(withAssignments&&!state.spaces.size){toast('请至少选择一个目标空间');return}
 var source=state.source||null;
 if(!source){source={id:'ds-'+Date.now(),type:state.type,brand:state.brand,assignments:[]};connectedSources.unshift(source)}
 source.name=state.name.trim();source.description=state.description.trim();source.type=state.type;source.brand=state.brand;if(!state.allocationOnly)source.status='连接正常';
 if(!state.allocationOnly){source.connection={host:state.host.trim(),port:state.port.trim(),user:state.user.trim(),database:state.database.trim()};source.meta=(state.database.trim()||'默认库')+' · '+state.host.trim()+':'+state.port.trim()}
 var manager=wizard.parentElement,organizationTargets=[],personalTargets=[];
 if(withAssignments){
  var targets=Array.from(state.spaces),stamp='2026-10-03 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});organizationTargets=targets.slice();personalTargets=targets.filter(function(name){return name==='个人空间'});source.pendingAssignments=source.pendingAssignments||[];
  var newTargets=organizationTargets.filter(function(space){return !spaceAlreadyAssigned(state,space)});
  state.selectedTables.forEach(function(key){
   newTargets.forEach(function(space){source.pendingAssignments.push({table:key,spaces:[space],fields:state.tableFields[key]?state.tableFields[key].slice():null,time:stamp,status:'待审批'})})
  });
  if(organizationTargets.length){var pendingApprovers=[];organizationTargets.forEach(function(space){approvalRuleForSpace(space).forEach(function(name){if(pendingApprovers.indexOf(name)<0)pendingApprovers.push(name)})});try{localStorage.setItem('knoraDataAllocationPending',JSON.stringify({source:source.name,type:state.type,tables:state.selectedTables,spaces:organizationTargets,time:stamp,applicant:'陈宇',approvers:pendingApprovers}))}catch(ignore){}}
 }
 renderConnectedList(list,leftSearch.value.trim());wizard.remove();if(activeType==='data')renderNonDocument();
 if(withAssignments&&organizationTargets.length)openAllocationSubmissionResult(manager,source,state,organizationTargets,personalTargets);else toast(state.mode==='edit'?'数据源连接已更新':'数据源已正式添加至连接列表')
}
