 layer.className='ds-wizard-layer feishu-ds-wizard-layer';manager.appendChild(layer);
 function formStep(){var connection=source&&source.connection||{};return '<div class="feishu-step-layout"><section class="feishu-operation-guide"><span class="step-kicker">操作说明</span><h3>在飞书开放平台创建 Knora 应用</h3><p>平台管理员仅需配置一次，后续每位用户通过个人 OAuth 授权同步自己可访问的文档。</p><ol><li><i>1</i><span><b>创建企业自建应用</b><small>进入飞书开放平台 → 开发者后台，创建“Knora 文档连接器”。</small></span></li><li><i>2</i><span><b>申请只读权限</b><small>开通云文档、云空间和知识库目录的读取权限。</small></span></li><li><i>3</i><span><b>配置 OAuth 回调</b><small>填写 Knora 回调地址，由企业管理员审核并发布应用。</small></span></li></ol><div class="feishu-security-note">App Secret 仅在服务端加密保存；用户访问令牌与应用凭证分开管理。</div></section><section class="feishu-credential-card"><span class="step-kicker">平台级配置</span><h3>录入应用凭证</h3><label><b>数据源名称</b><input data-feishu-source-name value="'+esc(source&&source.name||'飞书文档连接器')+'"></label><label><b><i>*</i> App ID</b><input data-feishu-app-id value="'+esc(connection.appId||'')+'" placeholder="cli_xxxxxxxxxxxxxxxx"></label><label><b><i>*</i> App Secret</b><input data-feishu-app-secret type="password" placeholder="请输入 App Secret"></label><label><b>OAuth 回调地址</b><div class="feishu-copy-field"><code>https://knora.example.com/oauth/feishu/callback</code><button type="button" data-feishu-copy>复制</button></div></label></section></div>'}
