 function render(){layer.innerHTML='<section class="feishu-ds-wizard"><header><div><button data-feishu-back>←</button>'+sourceMark('飞书文档','feishu')+'<span><h2>'+(editing?'编辑':'配置')+'飞书文档数据源</h2><p>企业应用配置 · 仅申请文档只读能力</p></span></div><button data-feishu-close>×</button></header><nav class="datasource-stepper-v2"><span class="active"><i>1</i>应用配置</span><em></em><span class="'+(step>=2?'active':'')+'"><i>2</i>测试连接</span><em></em><span class="'+(step>=3?'active':'')+'"><i>3</i>保存连接</span></nav><main>'+(step===1?formStep():step===2?testStep():completeStep())+'</main><footer><button data-feishu-close>取消</button><span></span>'+(step>1?'<button data-feishu-prev>上一步</button>':'')+'<button class="primary" data-feishu-next '+(step===2&&!tested?'disabled':'')+'>'+(step===1?'下一步':step===2?'下一步':editing?'保存修改':'保存并创建')+'</button></footer></section>';bind()}
