 var state={step:operation==='allocate'?3:1,mode:operation==='allocate'?'allocate':operation,allocationOnly:operation==='allocate',source:source,type:type,brand:source&&source.brand||brandForType(type),host:connection.host||defaults.host,port:connection.port||defaults.port,user:connection.user||defaults.user,password:defaults.password,database:connection.database||defaults.database,name:source&&source.name||'',description:source&&source.description||'',testing:false,connected:operation==='allocate',pending:new Set(),selectedTables:[],spaces:new Set(),tableQuery:'',spaceQuery:'',tableFields:{},focusSpace:''};
