function rowPermissionPane(item,prefix){var fields=rowPermissionFields(item),rules=item.rowPolicyRules||{};return '<section class="data-auth-main-pane row-permission-pane" data-row-resource-id="'+esc(item.id)+'" data-row-resource-name="'+esc(item.name)+'" data-'+prefix+'-auth-main-pane="row"><header class="row-permission-hero"><div><i>行</i><span><h3>行权限授权</h3><p>根据资源字段与当前用户属性动态过滤可查看的数据行</p></span></div><em>未命中规则默认不可见</em></header><nav class="row-permission-mode"><button class="active" data-row-mode="visual">可视化配置</button><button data-row-mode="script">脚本配置</button></nav><div class="row-permission-mode-pane active" data-row-mode-pane="visual"><div class="row-permission-guide"><b>1. 选择一个或多个字段</b><span>2. 配置字段与用户属性的比较或值映射</span><span>3. 生成策略脚本并保存</span></div><div class="row-permission-fields">'+fields.map(function(field,index){var configured=!!rules[field.api];return '<article class="'+(configured?'configured':'')+'"><label><input type="checkbox" data-row-field="'+esc(field.api)+'" '+(configured?'checked':'')+'><i>'+String(index+1).padStart(2,'0')+'</i><span><b>'+esc(field.name)+'</b><small>'+esc(field.api)+' · '+esc(field.type)+'</small></span></label><em data-row-rule-status="'+esc(field.api)+'">'+(configured?'已配置':'未配置')+'</em><button data-row-configure="'+esc(field.api)+'">配置</button></article>'}).join('')+'</div><section class="row-permission-script-preview"><header><div><b>最终策略脚本</b><small>可视化配置会同步生成可执行策略</small></div><button data-row-script-edit>编辑脚本</button></header><textarea data-row-script-preview readonly>'+esc(item.rowPolicyScript||rowPolicyScript(item))+'</textarea></section></div><div class="row-permission-mode-pane" data-row-mode-pane="script"><label class="row-permission-code"><span><b>行权限策略脚本</b><small>支持 row.字段、current_user.用户属性与 MAP 映射函数</small></span><textarea data-row-script-editor>'+esc(item.rowPolicyScript||rowPolicyScript(item))+'</textarea></label><aside><b>当前可用用户属性</b><span>current_user.name</span><span>current_user.employee_no</span><span>current_user.position</span><span>current_user.region</span><span>current_user.department</span><span>current_user.sensitivity_level</span></aside></div><footer class="row-permission-footer"><span><i></i>保存后，后续数据查询将在资源授权基础上追加行权限鉴权</span><button class="primary" data-row-policy-save>保存行权限策略</button></footer></section>'}
